{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Edaravone, a 3-methyl-1-phenylpyrazolone closely related to the query, has an absolute oral bioavailability of 57.3% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "In a fasted-condition Phase 1 study, oral edaravone at ~100 mg was estimated to have an absolute bioavailability of about 60%, supporting high F under the query's fasted condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Pirfenidone, an N-phenyl heterocycle with a methyl and carbonyl pattern similar to the query, is rapidly absorbed with high oral bioavailability in humans and nonclinical species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Clobazam, an N-phenyl heterocycle with N-methyl and carbonyl groups, shows 87-100% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Mavacamten, a structurally distinct N-heterocycle, has an estimated oral bioavailability of at least 85% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pethidine, an N-methyl phenylpiperidine, has absolute oral bioavailability around 50-60% in healthy subjects, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Fenspiride, a spirocyclic N-heterocycle, shows 90% absolute oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, well-absorbed pyrazolone (antipyrine/phenazone). All transferable experimental evidence from structurally related N-phenyl heterocycles and pyrazolones indicates oral bioavailability well above 20%, with several analogues showing 57-100% F. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself was retrieved; however, the query is a known pyrazolone and the retrieved analogues consistently support high F.",
    "Fasted-state-specific data are limited to edaravone; other analogues were not explicitly fasted, but food effects are not expected to be major for these small, well-absorbed heterocycles."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

